"use client";
/**
 * EosDesignPage: the Eos theme as one product's page, in any of its five looks. Morrow, a fictional app that runs
 * routines while you sleep, is shown in three views: Discover, the Connect Coffer page and the app on its Routines
 * page. A segmented control in the page's bar switches the look in place: the page and its views stay mounted, focus
 * stays on the control and the reader keeps their place: the heading in view (or else the section under the bar)
 * stays where it was on screen. Where motion is allowed the new look fades in over the old one (motion.ts); with
 * reduced motion it swaps at once. Every word comes from `content`; pass any part of it to change the copy.
 *
 * What differs between looks is tokens (tokens.ts) and the few layout choices each look names there: the side rail,
 * the card media, the Discover grid, the connect page's layout and how the app sits on the page.
 *
 * Inspired by rico (@_heyrico)'s twin visual vibe.
 */
import { useId, useRef, useState, type CSSProperties } from "react";
import { flushSync } from "react-dom";
import { EosAppShell, EosAppSidebar } from "./app-shell";
