.eos-dp-bar{position:sticky;top:0;z-index:30;display:flex;align-items:center;gap:16px;box-sizing:border-box;height:var(--eos-dp-bar);padding:0 clamp(12px,3vw,32px);background:var(--eos-bar);border-bottom:1px solid var(--eos-hairline);-webkit-backdrop-filter:blur(18px) saturate(1.4);backdrop-filter:blur(18px) saturate(1.4)}
