/** The switcher's segments: every look, by its title. */
export const EOS_LOOK_SEGMENTS: readonly EosSegment[] = EOS_LOOKS.map((look) => ({ value: look, label: EOS_LOOK_SPECS[look].title }));

/**
 * The reader's place, and where on screen it is: the heading of the first page section whose heading shows in full
 * below the bar, or else the first section still showing below the bar. None at the top of the page, which stays the
 * top.
 */
interface Place {
  node: Element;
  top: number;
}

function placeOf(main: HTMLElement | null, bar: HTMLElement | null): Place | null {
  if (!main || window.scrollY <= 0) return null;
  const line = bar?.getBoundingClientRect().bottom ?? 0;
  const sections = [...main.children].filter((child) => child.tagName === "SECTION");
  for (const section of sections) {
    const label = section.getAttribute("aria-labelledby");
    const heading = label ? (section.getRootNode() as Document | ShadowRoot).getElementById(label) : null;
    const box = heading?.getBoundingClientRect();
    if (heading && box && box.height > 0 && box.top >= line && box.bottom <= window.innerHeight) return { node: heading, top: box.top };
  }
  for (const section of sections) {
    const box = section.getBoundingClientRect();
    if (box.bottom > line) return { node: section, top: box.top };
  }
  return null;
}

/** Scroll by however far the reader's place moved in the new look, so it is where it was on screen. */
function keepPlace(place: Place | null) {
  if (!place) return;
  const moved = place.node.getBoundingClientRect().top - place.top;
  if (Math.abs(moved) >= 1) window.scrollBy(0, moved);
}

export interface EosDesignPageProps {
  /** The look, when the page around it holds the choice; pair it with onLookChange so the switcher can change it. */
  look?: EosLook;
  /** The look to start in when the page holds the choice itself. */
  defaultLook?: EosLook;
  onLookChange?: (look: EosLook) => void;
  /** Light or dark. By default each look's own: night is dark, the others light. */
  mode?: EosMode;
  /** The look switcher in the page's bar. */
  switcher?: boolean;
  /** Any part of the copy, over the Morrow defaults. */
  content?: Partial<EosDesignContent>;
  className?: string;
  style?: CSSProperties;
}

export function EosDesignPage({
  look,
  defaultLook = "pastel",
  onLookChange,
  mode,
  switcher = true,
  content,
  className,
  style,
}: EosDesignPageProps) {
  const [chosen, setChosen] = useControlled<EosLook>(look === undefined ? undefined : eosLook(look), eosLook(defaultLook), onLookChange);
  const current = eosLook(chosen);
  const spec = EOS_LOOK_SPECS[current];
  const { rail, detail } = spec.layout;
  const tone: EosMode = mode ?? spec.mode;
  const c: EosDesignContent = { ...EOS_MORROW, ...content };
  const [filter, setFilter] = useState("all");
  // The night look's page is the app, with its sidebar as the page's rail; on a narrow screen the app keeps its own.
  const wide = useMedia("(min-width: 901px)", true);
  const app = spec.layout.app === "page" && !wide ? "tile" : spec.layout.app;
  const bar = useRef<HTMLElement>(null);
  const main = useRef<HTMLElement>(null);
  const field = useRef<HTMLDivElement>(null);
  const id = useId();
  // The backdrop's glows drift slowly over its gradient while it shows; the grain holds still on top.
  useEosLoop(field, Boolean(spec.backdrop));
  // When a filter changes how many cards Discover holds, what follows it slides to its new place.
  const follow = useEosFollow(
    () => {
      const sections = main.current ? ([...main.current.children] as HTMLElement[]) : [];
      const at = sections.findIndex((el) => el.classList.contains("eos-discover"));
      return at < 0 ? [] : sections.slice(at + 1);
    },
    filter,
    current,
  );
  const filterTo = (next: string) => {
    if (next === filter) return;
    follow();
    setFilter(next);
  };

  const choose = (value: string) => {
    const next = eosLook(value);
    if (next === current) return;
    const place = placeOf(main.current, bar.current);
    eosCrossfade(() => {
      flushSync(() => setChosen(next));
      keepPlace(place);
    }, next);
  };

  return (
    <EosTheme look={current} mode={tone} className={cx("eos-dp", className)} style={style}>
      <style>{CSS}</style>
      {spec.backdrop && (
        <div ref={field} className="eos-dp-field" style={{ "--eos-dp-glow": `var(--eos-glow-${spec.backdrop})` } as CSSProperties} aria-hidden>
          <div className="eos-dp-drift eos-drift">
            <span data-petal="a" />
            <span data-petal="b" />
            <span data-petal="c" />
          </div>
          <span className="eos-dp-grain" />
        </div>
      )}
      <header ref={bar} className="eos-dp-bar">
        <p className="eos-dp-brand">
          <EosMark kind="sun" size={24} />
          {c.product}
        </p>
        {switcher && (
          <div className="eos-dp-switch">
            <span className="eos-dp-switch-label" aria-hidden>
              Look
            </span>
            <EosSegmentedControl segments={EOS_LOOK_SEGMENTS} value={current} onChange={choose} label="Look" size="sm" />
          </div>
        )}
      </header>
      <div className="eos-dp-body" data-rail={rail ?? "none"}>
        {rail === "index" && (
          <aside className="eos-dp-rail" aria-label="Routine categories">
            <EosCategoryIndex content={c} filter={filter} onFilter={filterTo} />
          </aside>
        )}
        {rail === "app" && (
          <aside className="eos-dp-rail" aria-label={`${c.product} sidebar`}>
            <EosAppSidebar defaultActive="routines" />
          </aside>
        )}
        <main ref={main} className="eos-dp-main">
          <EosDiscover content={c} filter={filter} onFilter={filterTo} headingLevel={1} />
          <EosDetailHeader
            from={c.detail.from}
            to={c.detail.to}
            title={c.detail.title}
            subline={c.detail.subline}
            about={c.detail.about}
            action={{ label: c.detail.action }}
            note={c.detail.note}
            quote={c.detail.quote}
          >
            {detail === "bento" && <EosBentoTiles content={c} />}
          </EosDetailHeader>
          <section className="eos-dp-app" data-app={app} aria-labelledby={`${id}-app`}>
            <div className="eos-dp-apphead">
              <h2 id={`${id}-app`} className="eos-dp-h">
                {c.shell.heading}
              </h2>
              <p className="eos-dp-lede">{c.shell.lede}</p>
            </div>
            <EosGradientBanner className="eos-dp-frame" gradient="dawn" shape="card" height="auto" petals={app === "field"} grain={app === "field"}>
              <EosAppShell
                className="eos-dp-window"
                chrome={app !== "page"}
                height={app === "page" ? "auto" : 740}
                mode={app === "page" ? tone : "dark"}
                title={c.shell.title}
              >
                <EosRoutinesPage content={eosRoutinesContent(c)} headingLevel={3} />
              </EosAppShell>
            </EosGradientBanner>
          </section>
        </main>
      </div>
    </EosTheme>
  );
}

