export interface EosDesignContent {
  product: string;
  tagline: string;
  discover: { title: string; lede: string; filters: readonly EosFilter[]; routines: readonly EosRoutine[]; empty: string };
  detail: {
    title: string;
    subline: string;
    from: EosConnectEnd;
    to: EosConnectEnd;
    about: EosAbout;
    action: string;
    note: string;
    quote: { text: string; by: string };
  };
  shell: {
    /** The app section's heading, over the app. */
    heading: string;
    /** A line under that heading. */
    lede: string;
    /** The app's own page: its title and subline. */
    title: string;
    subline: string;
    installed: string;
    discover: string;
    recommended: { heading: string; title: string; text: string; by: string; app: EosAppKind };
    more: string;
  };
  /** Every routine category, for the index. */
  index: readonly { value: string; label: string; count: number }[];
  stats: readonly EosStat[];
  upcoming: { title: string; runs: readonly EosRun[] };
  plans: { title: string; options: readonly EosPlan[]; chosen: string; action: string };
  overlay: { caption: string; action: string };
}

