/** The routines a filter shows: all of them (up to `limit`) or the ones in its category. */
export function eosRoutinesFor(routines: readonly EosRoutine[], filter: string, limit = routines.length): readonly EosRoutine[] {
  return filter === "all" ? routines.slice(0, limit) : routines.filter((r) => r.category === filter);
}

export interface EosDiscoverProps {
  content: EosDesignContent;
  /** The chosen filter; the page holds it, so the editorial index can set it too. */
  filter: string;
  onFilter: (value: string) => void;
  limit?: number;
  headingLevel?: 1 | 2;
  className?: string;
  style?: CSSProperties;
}

/** Discover: a heading and lede, pill filters, and the routines as market cards in the look's grid. */
export function EosDiscover({ content, filter, onFilter, limit = 6, headingLevel = 2, className, style }: EosDiscoverProps) {
  const look = useEosTheme()?.look;
  const grid = EOS_LOOK_SPECS[look ?? "pastel"].layout.grid;
  const id = useId();
  const shown = eosRoutinesFor(content.discover.routines, filter, limit);
  const Heading = `h${headingLevel}` as "h2";
  const list = useRef<HTMLDivElement>(null);
  const ghosts = useRef<HTMLDivElement>(null);
  const motion = eosMotion(look);
  // The heading, the lede and the pills rise first; the cards follow them.
  const riseOf = useEosListMotion({ list, ghosts, keys: shown.map((r) => r.id), offset: 3, look });
  return (
    <section className={cx("eos-discover", className)} style={style} aria-labelledby={`${id}-title`} data-grid={grid}>
      <style>{CSS}</style>
      <div className="eos-discover-head">
        <RiCompass3Line className="eos-discover-icon eos-rise" size={30} aria-hidden style={eosRiseStyle(0, motion)} />
        <Heading id={`${id}-title`} className="eos-discover-title eos-rise" style={eosRiseStyle(0, motion)}>
          {content.discover.title}
        </Heading>
        <p className="eos-discover-lede eos-rise" style={eosRiseStyle(1, motion)}>
          {content.discover.lede}
        </p>
      </div>
      <EosPillFilters
        items={content.discover.filters}
        value={filter}
        onChange={onFilter}
        label="Filter routines"
        className="eos-rise"
        style={eosRiseStyle(2, motion)}
      />
      <div ref={list} className="eos-discover-grid">
        <EosGhosts ref={ghosts} />
        {shown.map((r, i) => (
          <EosMarketCard
            key={r.id}
            data-eos-key={r.id}
            className="eos-rise"
            style={riseOf(r.id)}
            title={r.title}
            subline={r.subline}
            apps={r.apps}
            gradient={r.gradient}
            installs={r.installs}
            maker={r.maker}
            makerMark={r.makerMark}
            flip={i % 2 === 1}
            href={`#${r.id}`}
          />
        ))}
        {shown.length === 0 && <EosEmptyState text={content.discover.empty} action="Show all routines" onAction={() => onFilter("all")} />}
      </div>
    </section>
  );
}

export function EosEmptyState({ text, action, onAction }: { text: string; action: string; onAction: () => void }) {
  return (
    <div className="eos-empty eos-rise" role="status">
      <style>{CSS}</style>
      <p>{text}</p>
      <button type="button" onClick={onAction}>
        {action}
      </button>
    </div>
  );
}

/** Every routine category from A to Z with its count; choosing one filters Discover, choosing it again clears it. */
export function EosCategoryIndex({ content, filter, onFilter }: { content: EosDesignContent; filter: string; onFilter: (value: string) => void }) {
  const look = useEosTheme()?.look;
  const list = useRef<HTMLUListElement>(null);
  const mark = useRef<HTMLElement>(null);
  const buttons = useRef(new Map<string, HTMLButtonElement>());
  useEosIndicator({ host: list, indicator: mark, target: () => buttons.current.get(filter), choice: filter, opaque: true, look });
  const enter = useEosEntrance();
  return (
    <div className={cx("eos-index", enter && "eos-rise")} style={enter ? eosRiseStyle(1, eosMotion(look)) : undefined}>
      <style>{CSS}</style>
      <p className="eos-index-h">Categories, A to Z</p>
      <ul ref={list} className="eos-index-list">
        <EosIndicator ref={mark} as="li" />
        {content.index.map((entry) => (
          <li key={entry.value}>
            <button
              ref={(el) => {
                if (el) buttons.current.set(entry.value, el);
                else buttons.current.delete(entry.value);
              }}
              type="button"
              aria-pressed={filter === entry.value}
              onClick={() => onFilter(filter === entry.value ? "all" : entry.value)}
            >
              <span className="eos-index-t" data-text={entry.label}>
                {entry.label}
              </span>
              <span>{entry.count}</span>
            </button>
          </li>
        ))}
      </ul>
    </div>
  );
}

/** A tile on a vivid field: the gradient, its ink and its quieter ink. */
const field = (name: EosGradientName) =>
  ({
    "--eos-bt-fill": `var(--eos-gradient-${name})`,
    "--eos-bt-ink": `var(--eos-ink-${name})`,
    "--eos-bt-soft": `var(--eos-ink-soft-${name})`,
  }) as CSSProperties;

/** The stat tiles alternate a vivid field with a plain card. */
const STAT_FIELDS: readonly (EosGradientName | null)[] = ["orchid", null, "citrine", null];

/** The bento's other tiles: stats, the upcoming runs, a caption over a vivid field and a plan picker. */
export function EosBentoTiles({ content }: { content: EosDesignContent }) {
  const plans = content.plans.options;
  const [plan, setPlan] = useState(content.plans.chosen);
  const radios = useRef<(HTMLButtonElement | null)[]>([]);
  const id = useId();
  const chosen = plans.findIndex((p) => p.id === plan);
  const onPlanKey = (event: KeyboardEvent<HTMLButtonElement>, index: number) => {
    const next = rovingIndex(event.key, index, plans.length);
    const option = plans[next];
    if (next < 0 || !option) return;
    event.preventDefault();
    setPlan(option.id);
    radios.current[next]?.focus();
  };
  return (
    <>
      <style>{CSS}</style>
      {content.stats.map((stat, i) => {
        const name = STAT_FIELDS[i % STAT_FIELDS.length];
        return (
          <div key={stat.label} className="eos-bt eos-bt-stat" data-field={name ?? undefined} style={name ? field(name) : undefined}>
            <p className="eos-bt-label">{stat.label}</p>
            <div className="eos-bt-row">
              <p className="eos-bt-value">{stat.value}</p>
              {stat.change && <span className="eos-bt-change">{stat.change}</span>}
            </div>
          </div>
        );
      })}
      <section className="eos-bt eos-bt-col" aria-labelledby={`${id}-runs`}>
        <h3 className="eos-bt-h" id={`${id}-runs`}>
          {content.upcoming.title}
        </h3>
        <ol className="eos-bt-runs">
          {content.upcoming.runs.map((run) => (
            <li key={`${run.time}-${run.title}`}>
              <time>{run.time}</time>
              <EosAppGlyph app={run.app} size={22} />
              <span>{run.title}</span>
            </li>
          ))}
        </ol>
      </section>
      <section className="eos-bt eos-bt-overlay" data-field="blush" style={field("blush")} aria-label={content.overlay.caption}>
        <p className="eos-bt-overlay-text">{content.overlay.caption}</p>
        <button type="button" className="eos-bt-btn">
          {content.overlay.action}
        </button>
      </section>
      <section className="eos-bt eos-bt-col" aria-labelledby={`${id}-plans`}>
        <h3 className="eos-bt-h" id={`${id}-plans`}>
          {content.plans.title}
        </h3>
        <div className="eos-bt-plans" role="radiogroup" aria-labelledby={`${id}-plans`}>
          {plans.map((option, index) => {
            const on = option.id === plan;
            return (
              <button
                key={option.id}
                ref={(el) => {
                  radios.current[index] = el;
                }}
                type="button"
                role="radio"
                aria-checked={on}
                tabIndex={on || (chosen < 0 && index === 0) ? 0 : -1}
                className="eos-bt-plan"
                onClick={() => setPlan(option.id)}
                onKeyDown={(event) => onPlanKey(event, index)}
              >
                <span className="eos-bt-plan-name">{option.name}</span>
                <span className="eos-bt-plan-price">{option.price}</span>
                <span className="eos-bt-plan-note">{option.note}</span>
                <span className="eos-bt-plan-per">{option.per}</span>
              </button>
            );
          })}
        </div>
        {chosen >= 0 && (
          <button type="button" className="eos-bt-btn">
            {content.plans.action} {plans[chosen]?.name}
          </button>
        )}
      </section>
    </>
  );
}

/** The routines template's copy from this page's content: the first three routines run, the next two are new. */
export function eosRoutinesContent(content: EosDesignContent): EosRoutinesContent {
  const item = (r: EosRoutine): EosRoutineItem => ({ id: r.id, title: r.title, text: r.subline, apps: r.apps, href: `#${r.id}` });
  const shell = content.shell;
  return {
    title: shell.title,
    subline: shell.subline,
    installed: shell.installed,
    discover: shell.discover,
    running: content.discover.routines.slice(0, 3).map((r) => ({ ...item(r), schedule: r.schedule })),
    recommended: shell.recommended,
    more: shell.more,
    fresh: content.discover.routines.slice(3, 5).map((r) => ({ ...item(r), maker: r.maker })),
  };
}

// @zeus-internal
/** Small helpers the Eos pieces share. */
import { useCallback, useEffect, useLayoutEffect, useState } from "react";

export const cx = (...parts: (string | false | null | undefined)[]) => parts.filter(Boolean).join(" ");

export const useIsoLayoutEffect = typeof window === "undefined" ? useEffect : useLayoutEffect;

/** A value that is controlled when `value` is given and owned here otherwise. */
export function useControlled<T>(value: T | undefined, initial: T, onChange?: (next: T) => void) {
  const [own, setOwn] = useState(initial);
  const current = value === undefined ? own : value;
  const set = useCallback(
    (next: T) => {
      if (value === undefined) setOwn(next);
      onChange?.(next);
    },
    [value, onChange],
  );
  return [current, set] as const;
}

/**
 * Whether a media query matches. The server and the first render use `initial`, so markup hydrates; the real answer
 * follows once mounted, and changes as the window does.
 */
export function useMedia(query: string, initial = false): boolean {
  const [matches, setMatches] = useState(initial);
  useEffect(() => {
    if (typeof window === "undefined" || typeof window.matchMedia !== "function") return;
    const list = window.matchMedia(query);
    const update = () => setMatches(list.matches);
    update();
    list.addEventListener?.("change", update);
    return () => list.removeEventListener?.("change", update);
  }, [query]);
  return matches;
}

/** The index a roving-focus key moves to, or -1 for a key the group ignores. */
export function rovingIndex(key: string, index: number, count: number): number {
  if (count === 0) return -1;
  if (key === "ArrowRight" || key === "ArrowDown") return (index + 1) % count;
  if (key === "ArrowLeft" || key === "ArrowUp") return (index - 1 + count) % count;
  if (key === "Home") return 0;
  if (key === "End") return count - 1;
  return -1;
}

